    await ui.setAsOf(pg_uma, "2026-03-05");
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("role-row-vic").getByTestId("role-value")).toHaveText("clerk");
    await expect(pg_uma.getByTestId("role-row-wes").getByTestId("role-value")).toHaveText("viewer");
